// Statement steps must remain on the selected account's real URL, never a made-up ID.
for (const step of extendedGuides.find(item => item.id === "statements")!.steps.slice(1)) {
  step.routePattern = "^/operations/accounts/[^/]+/statement$";
}

export const extendedPageHelp = extendedGuides.filter(item => !["unsigned-move-in", "payments", "transfer", "move-out", "packages", "fulfilment", "tenant-defaults", "program-defaults"].includes(item.id))
  .map(item => ({ route: item.id === "statements" ? "/operations/accounts/[id]/statement" : item.steps[0].route,
    title: item.id === "merchandise" ? "Merchandise" : item.steps[0].screen, body: item.description, guideId: item.id }));
